// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: give alice 2 ether, warp to time 100, unlockTime = 110
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);
        vm.warp(100);
        vm.prank(alice);
        c.Put{value: 2 ether}(110);
        // After lock expires (warp to 200), alice calls Collect(1 ether)
        vm.warp(200);
        vm.prank(alice);
        bool ok;
        try c.Collect(1 ether) { ok = true; } catch { ok = false; }
        // Reference contract succeeds (Collect executed), buggy contract also succeeds but balance differs? 
        // Actually both succeed, but the difference is that reference Collect would revert if unlockTime > now (but it's 200 > 110, so both succeed).
        // Wait - the mutant sets unlockTime to _unlockTime (which is 110 in Put call) but reference uses max(110,100)=110. Both same here.
        // Need a scenario where mutant allows early withdrawal.
        // Use _unlockTime = 0. Then reference sets unlockTime = max(0, block.timestamp) = 100, mutant sets unlockTime = 0.
        // Then warp to 50 (before 100) - reference Collect reverts, mutant Collect succeeds.
        // Redo:
        vm.deal(alice, 2 ether);
        vm.warp(50);
        vm.prank(alice);
        c.Put{value: 2 ether}(0);
        // Now warp to 80 (still before reference's lock time 100, but after mutant's 0)
        vm.warp(80);
        vm.prank(alice);
        bool ok2;
        try c.Collect(1 ether) { ok2 = true; } catch { ok2 = false; }
        // Reference reverts (unlockTime=100 > now=80), mutant succeeds (unlockTime=0)
        assertTrue(!ok2, "Buggy contract should have allowed Collect, reference would have reverted");
        // Wait, we need the assertion that reference holds and bug breaks. Reference holds that Collect reverts (ok2 false). Bug breaks because Collect succeeds (ok2 true).
        // So assert that ok2 is false (the reference behavior). But bug would make it true, so test passes on reference and fails on mutant.
        // Actually we want test to PASS on reference (assertTrue(!ok2) passes since ok2 false) and FAIL on mutant (assertTrue(!ok2) fails since ok2 true).
        // That's correct.
    }
}

