import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Scenario: deposit 1 ether with _unlockTime = 0, then try Collect(1 ether) immediately
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.Put{value: 1 ether}(0);
        // Now block.timestamp == unlockTime for reference, < unlockTime for buggy
        // Try Collect(1 ether)
        vm.prank(user);
        bool ok;
        try c.Collect(1 ether) { ok = true; } catch { ok = false; }
        // Reference: revert because block.timestamp <= unlockTime (equal)
        // Buggy: succeed because unlockTime = 0 < block.timestamp
        // So reference has ok = false, buggy has ok = true
        assertTrue(!ok, "Reference should revert here, buggy allows");
    }
}

