pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 10 ether);
        uint amount = 1 ether;

        // Alice puts 1 ether with unlockTime = 0 (will set to block.timestamp)
        vm.prank(alice);
        c.Put{value: amount}(0);

        // Now call Collect(amount) – in reference, unlockTime == block.timestamp so collect reverts (strict > required).
        // In buggy, balance was subtracted instead of added, so acc.balance is less than MinSum (1 ether) so also reverts.
        // To observe divergence, we need a scenario where Collect succeeds in one but not the other.
        // Instead, we observe the balance after the Put call: reference adds, bug subtracts.
        // Also ensure MinSum satisfied.
        (uint unlockTime, uint balance) = c.Acc(alice);
        // In reference: balance == 1 ether; in buggy: balance == 0 (since 1 - 1 = 0)
        assertTrue(balance == (1 ether - amount) ? false : true); 
    }
}

