pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up: give user1 some ether
        address user1 = address(0x1234);
        vm.deal(user1, 2 ether);

        // First put: lock 1 ether with unlockTime = 0 => will be set to block.timestamp
        vm.prank(user1);
        c.Put{value: 1 ether}(0);

        // Warp past the unlock time
        vm.warp(block.timestamp + 1);

        // Now try to collect exactly 1 ether (MinSum)
        vm.prank(user1);
        bool ok;
        try c.Collect(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: Collect succeeds because unlockTime was set to block.timestamp (+1 passed)
        // Bug: Collect reverts because unlockTime is always block.timestamp (same as current block.timestamp? No, we warped)
        // Actually both set unlockTime to block.timestamp at the time of Put, then we warp +1
        // Reference: unlockTime = (0 > block.timestamp? 0 : block.timestamp) = block.timestamp at Put time
        // Bug: unlockTime = block.timestamp at Put time
        // So both same: both should succeed? Wait, the difference: reference uses _unlockTime if > current, else current;
        // Here _unlockTime=0, so both set to block.timestamp. That's identical.
        // Need a case where _unlockTime > block.timestamp.

        // Reset with a new scenario:
        vm.warp(1000);
        vm.prank(user1);
        c.Put{value: 1 ether}(2000); // unlockTime proposed = 2000

        // At current time 1000, reference sets unlockTime = 2000 (since 2000 > 1000)
        // Bug sets unlockTime = 1000 (block.timestamp)

        // Now warp to 1500 (before proposed unlock 2000 but after bug's unlock 1000)
        vm.warp(1500);

        vm.prank(user1);
        bool ok2;
        try c.Collect(1 ether) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // Reference: unlockTime=2000 > block.timestamp=1500 => Collect reverts => ok2 = false
        // Bug: unlockTime=1000 < block.timestamp=1500 => Collect succeeds => ok2 = true
        // But we need the assertion to hold for reference and break for bug:
        // So we assert ok2 == false (reference holds, bug breaks because it would be true)
        assertTrue(!ok2);
    }
}

