        (bool ok, ) = address(c).call{value: 1 ether}(abi.encodeWithSelector(bytes4(keccak256("Collect(uint256)")), 1 ether));
        // In reference, ok == false and balance unchanged (1 ether)
        // In buggy, ok == true (no revert) and balance becomes 0
        bool balanceChanged = (c.Acc(actor).balance == 0 ether);
        // The reference leaves balance == 1 ether, so balanceChanged is false
        // The buggy leaves balance == 0 ether, so balanceChanged is true
        // We assert that balanceChanged is false (reference behavior)
        assertTrue(!balanceChanged);
    }
}

